int XML_SetElementPrefix(XML_Parser parser, ELEMENT_TYPE* elementType) {
  const XML_Char *name = elementType->name;
  int idx;
  XML_Memory_Handling_Suite *mem = &parser->mem;
  XML_Char *prefixStart;
  XML_DTD *dtd = parser->dtd;

  if (!name)
    return 0;

  for (idx = 0; name[idx]; idx++) {
    if (name[idx] == ':') {
      break;
    }
  }

  if (name[idx] != ':')
    return 1;

  if (idx == 0)
    return 0;

  if (mem->PoolAppendN(&dtd->prefixPool, name, idx) == -1)
    return 0;

  prefixStart = mem->PoolStart(&dtd->prefixPool);
  XML_Prefix *prefix = XML_GetPrefix(dtd, prefixStart);

  if (!prefix)
    return 0;

  elementType->prefix = prefix;
  mem->PoolClear(&dtd->prefixPool);

  return 1;
}

int XML_SetElementTypePrefix(XML_Parser parser, ELEMENT_TYPE* elementType) {
  const XML_Char* name = elementType->name;
  int len = 0;
  const XML_Char* colon = NULL;

  while (name[len] != '\0') {
    if (name[len] == ':') {
      if (colon == NULL) {
        colon = &name[len];
      } else {
        return 0; /* Multiple colons, invalid */
      }
    }
    len++;
  }

  if (colon == NULL) {
    /* No colon, no prefix to set */
    elementType->prefix = NULL;
    return 1;
  }

  if (colon == name) {
    return 0; /* Colon at the start, invalid */
  }

  /* Copy the prefix part into a buffer */
  int prefixLen = colon - name;
  XML_ParserInternal* p = (XML_ParserInternal*)parser;
  XML_MemoryPool* pool = p->m_pool;

  XML_Char* prefix = (XML_Char*)XML_MemoryPoolGrow(pool, prefixLen + 1);
  if (!prefix)
    return 0;

  int i;
  for (i = 0; i < prefixLen; i++) {
    prefix[i] = name[i];
  }
  prefix[prefixLen] = '\0';

  /* Look up the prefix in DTD prefix table */
  XML_DTD* dtd = p->m_dtd;
  XML_Prefix* foundPrefix = NULL;
  for (int j = 0; j < dtd->numPrefixes; j++) {
    if (XML_strcmp(dtd->prefixes[j].name, prefix) == 0) {
      foundPrefix = &dtd->prefixes[j];
      break;
    }
  }

  if (!foundPrefix) {
    return 0; /* Prefix not found */
  }

  elementType->prefix = foundPrefix;
  return 1;
}

int XML_SetDtdPrefixForElementType(XML_Parser parser, ELEMENT_TYPE *elementType) {
  const XML_Char *name = elementType->name;
  size_t nameLength = 0;
  const XML_Char *colonPos = NULL;

  if (!parser || !elementType || !name) {
    return 0;
  }

  while (name[nameLength] != '\0') {
    if (name[nameLength] == ':') {
      colonPos = name + nameLength;
      break;
    }
    nameLength++;
  }

  if (!colonPos || colonPos == name) {
    return 0;
  }

  XML_Memory_Node *prefixNode = XML_MemPool_Add(parser->memPool, name, colonPos - name);
  if (!prefixNode) {
    return 0;
  }

  XML_DTD *dtd = parser->dtd;
  if (!dtd) {
    return 0;
  }

  XML_Prefix *prefix = (XML_Prefix *)HashTable_Lookup(dtd->prefixTable, (const XML_Char *)prefixNode->data);
  if (!prefix) {
    XML_MemPool_Remove(parser->memPool, prefixNode);
    return 0;
  }

  elementType->prefix = prefix;
  return 1;
}

int XML_SetElementTypePrefix(XML_Parser parser, ELEMENT_TYPE* elementType) {
  const XML_Char *name = elementType->name;
  const XML_Char *colon = strchr(name, ':');
  if (colon == NULL)
    return 1; /* no prefix */

  int len = (int)(colon - name);
  if (len == 0)
    return 0; /* invalid empty prefix */

  XML_Memory_Handling_Suite *mem = &parser->m_memory;
  void *prefixPool = XML_PoolCreate(mem);
  if (!prefixPool)
    return 0;

  XML_Char *prefix = (XML_Char *)mem->m_alloc(mem->m_data, len * sizeof(XML_Char));
  if (!prefix) {
    mem->m_free(prefixPool);
    return 0;
  }

  memcpy(prefix, name, len * sizeof(XML_Char));
  XML_DTD *dtd = parser->m_dtd;
  XML_Prefix *existingPrefix = (XML_Prefix *)XML_HashtableLookup(dtd->prefixes, prefix);
  if (!existingPrefix) {
    mem->m_free(prefix);
    mem->m_free(prefixPool);
    return 0;
  }

  elementType->prefix = existingPrefix;
  mem->m_free(prefixPool);
  return 1;
}

